Script.Inputs = { prompt: 'string', token: 'string' };
Script.Outputs = { body: 'object', headers: 'object', send: 'signal' };

// Run builds the request from the prompt as it is now, then asks the stream to connect.
// `token` is the signed-in person's token for your own endpoint, never a provider key in the page.
Script.Signals.run = function () {
  Script.setOutputs({
    body: { stream: true, messages: [{ role: 'user', content: Script.Inputs.prompt || '' }] },
    headers: { Authorization: 'Bearer ' + (Script.Inputs.token || '') }
  });
  Script.Outputs.send();
};
